public class FileUtils {
    /**
     * Returns the index of the last directory separator character.
     * This method will handle a file in either Unix or Windows format.
     * The position of the last forward or backslash is returned.
     * The output will be the same irrespective of the machine that the code is running on.
     *
     * @param filename the filename to find the last path separator in, null returns -1
     * @return the index of the last separator character, or -1 if there is no such character
     */
    public static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf('/');
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(indexOfLastSeparator("/path/to/file.txt")); // Output: 10
        System.out.println(indexOfLastSeparator("C:\\path\\to\\file.txt")); // Output: 10
        System.out.println(indexOfLastSeparator("file.txt")); // Output: -1
        System.out.println(indexOfLastSeparator(null)); // Output: -1
    }
}

