import java.io.IOException;

public class CustomByteArrayOutputStream extends ByteArrayOutputStream {

    @Override
    public void write(final byte b[], final int off, final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException();
        } else if ((off < 0) || (off > b.length) || (len < 0) ||
                   ((off + len) > b.length) || ((off + len) < 0)) {
            throw new IndexOutOfBoundsException();
        } else if (len == 0) {
            return;
        }
        int newcount = count + len;
        if (newcount > buf.length) {
            buf = copyOf(buf, Math.max(buf.length << 1, newcount));
        }
        System.arraycopy(b, off, buf, count, len);
        count = newcount;
    }

    private byte[] copyOf(byte[] original, int newLength) {
        byte[] copy = new byte[newLength];
        System.arraycopy(original, 0, copy, 0, Math.min(original.length, newLength));
        return copy;
    }

    public static void main(String[] args) {
        CustomByteArrayOutputStream baos = new CustomByteArrayOutputStream();
        byte[] data = {1, 2, 3, 4, 5};
        try {
            baos.write(data, 1, 3);
            System.out.println("Written bytes: " + baos.toString());
        } catch (IOException e) {
