import java.lang.Character;

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type.equals(Character.class)) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() == 1) {
                return strValue.charAt(0);
            } else {
                throw new Exception("Cannot convert string to Character: " + value);
            }
        } else {
            throw new Exception("Unsupported conversion from " + value.getClass().getName() + " to Character");
        }
    } else {
        throw new Exception("Unsupported conversion to " + type.getName());
    }
}

