import org.apache.commons.beanutils.BeanMap;

import java.util.Map;

public class CustomBeanMap extends BeanMap {

    public CustomBeanMap(Object bean) {
        super(bean);
    }

    /**
     * Puts all of the writable properties from the given BeanMap into this BeanMap. Read-only and Write-only properties will be ignored.
     * @param map  the BeanMap whose properties to put
     */
    public void putAllWriteable(BeanMap map) {
        for (Object key : map.keySet()) {
            if (map.isWriteable(key)) {
                this.put(key, map.get(key));
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        ExampleBean bean1 = new ExampleBean();
        ExampleBean bean2 = new ExampleBean();

        CustomBeanMap map1 = new CustomBeanMap(bean1);
        CustomBeanMap map2 = new CustomBeanMap(bean2);

        // Set some properties on bean1
        map1.put("writableProperty", "value1");
        map1.put("readOnlyProperty", "value2");

        // Copy writable properties from bean1 to bean2
        map2.putAllWriteable(map1);

        // Output properties of bean2
        System.out.println("Writable Property: " + map2.get("writableProperty"));
        System.out.println("Read-Only Property: " + map2.get("readOnlyProperty"));
    }
}

