import java.io.IOException;
import java.io.InputStream;

public class ByteReader {
    private InputStream inputStream;
    private byte[] buffer;
    private int bufferSize;
    private int bufferPosition;

    public ByteReader(InputStream inputStream, int bufferSize) {
        this.inputStream = inputStream;
        this.bufferSize = bufferSize;
        this.buffer = new byte[bufferSize];
        this.bufferPosition = bufferSize; // Initialize to bufferSize to trigger a refill on the first read
    }

    public byte readByte() throws IOException {
        if (bufferPosition >= bufferSize) {
            refillBuffer();
        }
        if (bufferPosition >= bufferSize) {
            throw new IOException("No more data available");
        }
        return buffer[bufferPosition++];
    }

    private void refillBuffer() throws IOException {
        bufferPosition = 0;
        int bytesRead = inputStream.read(buffer);
        if (bytesRead == -1) {
            bufferPosition = bufferSize; // Mark as empty
        } else if (bytesRead < bufferSize) {
            // Shift the remaining bytes to the beginning of the buffer
            System.arraycopy(buffer, bytesRead, buffer, 0, bufferSize - bytesRead);
            bufferPosition = bufferSize - bytesRead;
        }
    }
}

