            node.prev.next = node.next;
        } else {
            head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }
        size--;
        return node;
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public ListNodeImpl<E> getHead() {
        return head;
    }
}

public class Main {
    public static void main(String[] args) {
        DoublyLinkedList<Integer> list1 = new DoublyLinkedList<>();
        DoublyLinkedList<Integer> list2 = new DoublyLinkedList<>();

        list1.addListNode(new ListNodeImpl<>(1));
        list1.addListNode(new ListNodeImpl<>(2));
        list1.addListNode(new ListNodeImpl<>(3));

        list2.moveAllListNodes(list1);

        System.out.println("List 1 size: " + list1.size()); // Should print 0
        System.out.println("List 2 size: " + list2.size()); // Should print 3
    }
}

