            resultMap.put(vertex, v);
        }
        for (String vertex : part2) {
            V v = target.addVertex();
            resultMap.put(vertex, v);
        }

        // Add edges to form a complete bipartite graph
        for (String vertex1 : part1) {
            for (String vertex2 : part2) {
                target.addEdge(resultMap.get(vertex1), resultMap.get(vertex2));
            }
        }
    }

    public static void main(String[] args) {
        SimpleGraph<String, DefaultEdge> graph = new SimpleGraph<>(DefaultEdge.class);
        Map<String, String> resultMap = new HashMap<>();
        BipartiteGraphGenerator<String, DefaultEdge> generator = new BipartiteGraphGenerator<>();
        generator.generateGraph(graph, resultMap);

        // Print the graph vertices and edges
        System.out.println("Vertices: " + graph.vertexSet());
        System.out.println("Edges: " + graph.edgeSet());
    }
}

