private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            // 1-byte character
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            // 2-byte character
            if (bb.hasRemaining()) {
                byte b2 = bb.get();
                sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
            } else {
                break;
            }
        } else if ((b & 0xF0) == 0xE0) {
