                    break;
                }
            } else {
                break;
            }
        } else if ((b & 0xF8) == 0xF0) {
            // 4-byte character
            if (bb.hasRemaining()) {
                byte b2 = bb.get();
                if (bb.hasRemaining()) {
                    byte b3 = bb.get();
                    if (bb.hasRemaining()) {
                        byte b4 = bb.get();
                        int codepoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
                        sb.append(Character.toChars(codepoint));
                    } else {
                        break;
                    }
