import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class StringUnescaper {

    /**
     * <p>Unescapes any Java literals found in the <code>String</code>. For example, it will turn a sequence of <code>'\'</code> and <code>'n'</code> into a newline character, unless the <code>'\'</code> is preceded by another <code>'\'</code>.</p>
     * @param str the <code>String</code> to unescape, may be null
     * @return a new unescaped <code>String</code>, <code>null</code> if null string input
     */
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        Pattern p = Pattern.compile("\\\\(\\p{XDigit}{1,4}|.)");
        Matcher m = p.matcher(str);

        while (m.find()) {
            String escape = m.group(1);
            int codePoint;

            if (escape.length() == 1) {
                codePoint = escape.charAt(0);
            } else {
                codePoint = Integer.parseInt(escape, 16);
            }

            sb.append(Character.toChars(codePoint));
        }

        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            String escaped = "This is a newline:\\nAnd this is a tab:\\t";
            String unescaped = unescapeJava(escaped);
            System.out.println(unescaped);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

