import java.util.ArrayList;
import java.util.List;

public class EnumerationUtils {

    /**
     * Copy the given Enumeration into a String array. The Enumeration must contain String elements only.
     * @param enumeration the Enumeration to copy
     * @return the String array (<code>null</code> if the passed-in Enumeration was <code>null</code>)
     */
    public static String[] toStringArray(Enumeration<String> enumeration) {
        if (enumeration == null) {
            return null;
        }

        List<String> list = new ArrayList<>();
        while (enumeration.hasMoreElements()) {
            list.add(enumeration.nextElement());
        }

        return list.toArray(new String[0]);
    }

    public static void main(String[] args) {
        // Example usage
        Enumeration<String> enumeration = new Enumeration<String>() {
            private final String[] elements = {"apple", "banana", "cherry"};
            private int index = 0;

            @Override
            public boolean hasMoreElements() {
                return index < elements.length;
            }

            @Override
            public String nextElement() {
                if (!hasMoreElements()) {
                    throw new java.util.NoSuchElementException();
                }
                return elements[index++];
            }
        };

        String[] array = toStringArray(enumeration);
        for (String s : array) {
            System.out.println(s);
        }
    }
}

