import java.util.Arrays;

public class StringSplitter {

    /**
     * Split a String at the first occurrence of the delimiter. Does not include the delimiter in the result.
     * @param toSplit the string to split
     * @param delimiter to split the string up with
     * @return a two element array with index 0 being before the delimiter, and index 1 being after the delimiter (neither element includes the delimiter); or <code>null</code> if the delimiter wasn't found in the given input String
     */
    public static String[] split(String toSplit, String delimiter) {
        if (toSplit == null || delimiter == null || delimiter.isEmpty()) {
            return null;
        }

        int index = toSplit.indexOf(delimiter);
        if (index == -1) {
            return null;
        }

        String beforeDelimiter = toSplit.substring(0, index);
        String afterDelimiter = toSplit.substring(index + delimiter.length());

        return new String[]{beforeDelimiter, afterDelimiter};
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(Arrays.toString(split("hello.world", "."))); // [hello, world]
        System.out.println(Arrays.toString(split("hello.world", "o"))); // [hell, .world]
        System.out.println(Arrays.toString(split("hello.world", "x"))); // null
        System.out.println(Arrays.toString(split("hello.world", "")));  // null
        System.out.println(Arrays.toString(split(null, ".")));          // null
    }
}

