public class NameAbbreviator {

    /**
     * Abbreviate name.
     * @param buf buffer to append abbreviation.
     * @param nameStart start of name to abbreviate.
     */
    public void abbreviate(final int nameStart, final StringBuffer buf) {
        // Assuming the name is a space-separated string
        String name = buf.substring(nameStart);
        StringTokenizer tokenizer = new StringTokenizer(name);

        while (tokenizer.hasMoreTokens()) {
            String token = tokenizer.nextToken();
            if (tokenizer.hasMoreTokens()) {
                buf.append(token.charAt(0)).append(".");
            } else {
                buf.append(token);
            }
        }
    }

    public static void main(String[] args) {
        NameAbbreviator abbreviator = new NameAbbreviator();
        StringBuffer buf = new StringBuffer("John Doe Smith");
        abbreviator.abbreviate(0, buf);
        System.out.println(buf.toString()); // Output: J.D.Smith
    }
}

