import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;

public class ByteBufferAggregator {
    private List<ByteBuffer> buffers;

    public ByteBufferAggregator() {
        this.buffers = new ArrayList<>();
    }

    public void addBuffer(ByteBuffer buffer) {
        this.buffers.add(buffer);
    }

    /**
     * Returns a single byte array containing all the contents written to the buffer(s).
     */
    public final byte[] toByteArray() {
        int totalSize = 0;
        for (ByteBuffer buffer : buffers) {
            totalSize += buffer.remaining();
        }

        byte[] result = new byte[totalSize];
        int position = 0;
        for (ByteBuffer buffer : buffers) {
            int length = buffer.remaining();
            buffer.get(result, position, length);
            position += length;
        }

        return result;
    }

    public static void main(String[] args) {
        ByteBufferAggregator aggregator = new ByteBufferAggregator();
        aggregator.addBuffer(ByteBuffer.wrap(new byte[]{1, 2, 3}));
        aggregator.addBuffer(ByteBuffer.wrap(new byte[]{4, 5, 6}));

        byte[] result = aggregator.toByteArray();
        for (byte b : result) {
            System.out.print(b + " ");
        }
    }
}

