import java.io.IOException;
import java.io.InputStream;

public class ProtocolMessageParser {

    private final InputStream inputStream;

    public ProtocolMessageParser(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    /**
     * Attempt to read a field tag, returning zero if we have reached EOF. Protocol message parsers use this to read tags, since a protocol message may legally end wherever a tag occurs, and zero is not a valid tag number.
     */
    public int readTag() throws IOException {
        int firstByte = inputStream.read();
        if (firstByte == -1) {
            return 0; // EOF
        }
        int secondByte = inputStream.read();
        if (secondByte == -1) {
            return 0; // EOF
        }
        return (firstByte & 0xFF) | ((secondByte & 0xFF) << 8);
    }

    public static void main(String[] args) {
        // Example usage
        try (InputStream inputStream = System.in) {
            ProtocolMessageParser parser = new ProtocolMessageParser(inputStream);
            int tag = parser.readTag();
            System.out.println("Read tag: " + tag);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

